void custom_handler(int sig) {
    /* Signal handling code */
}

// 1. Set a handler for the signal
signal(SIGINT, custom_handler);

// 2. Simulate the signal event
// Sending SIGINT (interrupt)
int status = raise(SIGINT);

// 3. Check status (0 indicates success)
if (status != 0) {
    // Handle error (signal could not be raised)
}

// Common signals: SIGTERM, SIGKILL, SIGABRT, SIGFPE, SIGSEGV
// Note: raise() acts only on the calling thread.
// Use kill() to send signals across processes.
// raise(SIGKILL) or raise(SIGSTOP) cannot be ignored or handled.
